"use client";

import { useParams } from "next/navigation";
import { useEffect, useState } from "react";
import axios from "axios";
import { GoogleMap, LoadScript, Marker } from "@react-google-maps/api";


interface Hotel {
  name: string;
  vicinity: string;
  geometry: {
    location: {
      lat: number;
      lng: number;
    };
  };
}

interface GeocodeResponse {
  results: {
    geometry: {
      location: {
        lat: number;
        lng: number;
      };
    };
  }[];
}

interface PlacesResponse {
  results: Hotel[];
  status: string;
}


const containerStyle = {
  width: "100%",
  height: "500px",
};


const defaultCenter = {
  lat: 28.6139,
  lng: 77.209,
};

const GOOGLE_MAPS_API_KEY = process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY;

const HotelFinder = () => {
  const { city } = useParams();
  const [hotels, setHotels] = useState<Hotel[]>([]);
  const [mapCenter, setMapCenter] = useState(defaultCenter);

  useEffect(() => {
    if (city) {
      fetchHotels(city as string);
    }
  }, [city]);

  const fetchHotels = async (searchTerm: string) => {
    try {
      
      const geoResponse = await axios.get<GeocodeResponse>(
        `https://maps.googleapis.com/maps/api/geocode/json`,
        {
          params: {
            address: searchTerm,
            key: GOOGLE_MAPS_API_KEY,
          },
        }
      );

      if (!geoResponse.data.results.length) {
        console.warn("⚠ No location found!");
        return;
      }

      const { lat, lng } = geoResponse.data.results[0].geometry.location;
      setMapCenter({ lat, lng });

      
      const placesResponse = await axios.get<PlacesResponse>(
        `https://maps.googleapis.com/maps/api/place/nearbysearch/json`,
        {
          params: {
            location: `${lat},${lng}`,
            radius: 5000,
            type: "lodging",
            key: GOOGLE_MAPS_API_KEY,
          },
        }
      );

      if (placesResponse.data.status !== "OK") {
        console.error("API Error:", placesResponse.data.status);
        return;
      }

      setHotels(placesResponse.data.results || []);
    } catch (error) {
      console.error("❌ Fetch error:", error);
    }
  };

  return (
    <div className="flex gap-5 p-5">
      <div className="w-3/5">
        <div className="mt-4">
          {hotels.length > 0 ? (
            hotels.map((hotel, index) => (
              <div key={index} className="p-3 border-b">
                <h3 className="text-lg font-semibold">{hotel.name}</h3>
                <p>{hotel.vicinity}</p>
              </div>
            ))
          ) : (
            <p className="text-gray-500">No hotels found</p>
          )}
        </div>
      </div>

      
      <div className="w-2/5">
        {GOOGLE_MAPS_API_KEY ? (
          <LoadScript googleMapsApiKey={GOOGLE_MAPS_API_KEY}>
            <GoogleMap
              mapContainerStyle={containerStyle}
              center={mapCenter}
              zoom={14}
            >
              {hotels.map((hotel, index) => (
                <Marker key={index} position={hotel.geometry.location} />
              ))}
            </GoogleMap>
          </LoadScript>
        ) : (
          <p className="text-gray-500">Google Maps API key is missing</p>
        )}
      </div>
    </div>
  );
};

export default HotelFinder;
